function main() {
    const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
    const s = input[0] || "";
    const len = s.length;
    let flag = 0;
    const ans = "CODEFORCES";

    for (let i = 0; i < len; i++) {
        let val = [];
        let j, k;
        for (j = 0; j < i; j++)
            val[j] = s[j];
        k = i;
        for (j = len - 10 + i; j < len; j++) {
            val[k] = s[j];
            k++;
        }
        for (j = 0; j < 10; j++) {
            if (val[j] === ans[j])
                flag = 1;
            else {
                flag = 0;
                break;
            }
        }
        if (flag === 1)
            break;
    }
    if (flag === 0)
        console.log("NO");
    else
        console.log("YES");
}

main();

